"""Retain scoped classification, choice mappings, and capability evidence."""
import hashlib,importlib.util,json,re
from pathlib import Path
H=Path(__file__).resolve().parent;R=H.parents[2]
spec=importlib.util.spec_from_file_location('g',H.with_suffix('.py'));g=importlib.util.module_from_spec(spec);spec.loader.exec_module(g)
def save(n,x):(H/n).write_text(json.dumps(x,indent=2)+'\n')
rows=[];maps=[];plots=[]
for mid,q in g.SOURCES.items():
 level=q.get(':question/difficulty',{}).get(':db/ident','unclassified').split('/')[-1];f=q[':question/answer-fields'][0];assets=re.findall(r'!\[.*?\]\((.*?)\)',q[':question/problem']);complete=bool(q.get(':question/worked-solution')and f.get(':answer-field/correct')and level!='unclassified')
 rows.append({'source_db_id':q[':db/id'],'source_ma_id':mid,'source_uuid':q[':question/id'],'level':level,'template':mid,'bank_profile':'source:'+mid,'fields':[{'key':f[':answer-field/key'],'type':f[':answer-field/type'][':db/ident'],'choices':len(f[':answer-field/choices'])}],'plot_rating':'moderate'if assets else'none','complete':complete,'normal_sampling':mid in g.DEFAULTS.values(),'reason':'Standalone parametric arc-length setup; formula, two derivatives, substitution and simplification. Each source retained as a distinct solution/choice profile pending any proven merge.'})
 if complete:
  x,y,a,b,fs=g.evidence(mid)
  maps.append({'source':mid,'source_prompt':q[':question/problem'],'source_solution':q[':question/worked-solution'],'coordinates':[str(x),str(y)],'bounds':[str(a),str(b)],'bank_profile':'source:'+mid,'choices':[{'source_answer_uuid':ans[':answer/id'],'source_field_uuid':f[':answer-field/id'],'exact_value':ans[':answer/value'],'parameterized_integrand':str(expr),'correct':ans[':answer/id']==f[':answer-field/correct'][':answer/id'],'recipe_interpretation':'correct derivative norm'if ans[':answer/id']==f[':answer-field/correct'][':answer/id']else'observed complete expression pattern; misconception not inferred'}for ans,expr in zip(f[':answer-field/choices'],fs)]})
 for asset in assets:
  p=Path('/media/jake/SSD/EDB/math')/asset
  plots.append({'source':mid,'path':asset,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'role':'Prompt supplementary sketch of the supplied curve, oriented solid interval with labeled endpoints; dotted continuation, black x/y axes, blue curve and arrow. No solution or answer plots.','content_inspected':True,'reuse':'evidence-only original parameters; not reused for changed curves','normal_sampler':False})
summary={l:{'source_templates':sum(r['level']==l for r in rows),'field_types':['radio/math'],'profiles':sum(r['level']==l for r in rows),'template_ids':[r['template']for r in rows if r['level']==l]}for l in ('easy','moderate','hard','unclassified')}
save('classification.json',{'basis':g.SNAP['basis'],'lineage':g.SNAP['lineage'],'knowledgePoint':g.KP_ID,'summary':summary,'sources':rows,'canonical_example_excluded':True,'unresolved':['q-15155 lacks difficulty, worked solution, and correct link; excluded without modifying source.','Nine complete families support exact evidence replay only; no normal sampling certified.']})
save('source-choice-mapping.json',maps);save('plot-extraction.json',plots)
save('capabilities.json',{'knowledgePoint':g.KP_ID,'generator_id':g.GENERATOR_UUID,'script':str(H.with_suffix('.py').relative_to(R)),'supported_levels':list(g.LEVELS),'normal_families':g.DEFAULTS,'finite_variant_limits':{level:len(g.domain(mid))for level,mid in g.DEFAULTS.items()},'exceptions':[{'level':'easy','status':'unsupported','evidence':'No rated easy sources. The two bounded families require trigonometric derivatives and expansion; labeling them easy would change observed classification. This is a package capability bound, not a proof that an easy arc-length problem is impossible. New evidence reopens classification.','nominal_shortage':5},{'source':'q-15155','status':'unsupported','evidence':'Missing key, difficulty and solution; preserved unchanged, does not count as inventory.'},{'families':'nine other complete source profiles','status':'replay-only','evidence':'Exact banks retained and replayed; not exposed to normal generation. Parameterized profiles and changing diagrams would need additional extraction/validation.'}],'distinctness':'Squared coordinate derivatives plus ordered bounds; excludes translations, derivative signs, bank, seed and choice order. Exclude all existing source/canonical/generated task fingerprints, including shown tasks.','shortage_policy':'Never count unsupported/evidence-only instances as filled; finite domain exhaustion remains explicit.'})
